function studioEnvironment(renderer){const images=[];for(let face=0;face<6;face++){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d'),gradient=x.createLinearGradient(0,0,0,256);gradient.addColorStop(0,'#8e9da7');gradient.addColorStop(.45,'#536575');gradient.addColorStop(1,'#202b32');x.fillStyle=gradient;x.fillRect(0,0,256,256);x.fillStyle=face===2?'#ffffff':'#cfdae0';if(face!==3){x.fillRect(24,20,48,176);x.fillRect(192,48,28,128);}images.push(c);}const cube=new THREE.CubeTexture(images);cube.colorSpace=THREE.SRGBColorSpace;cube.needsUpdate=true;const generator=new THREE.PMREMGenerator(renderer),target=generator.fromCubemap(cube);cube.dispose();generator.dispose();return target;}
